import pyomo.environ as pyo

DATA = {
    "products": ["road", "mountain"],
    "resources": ["grinder", "polisher"],
    "profit": {"road": 70, "mountain": 100},
    "usage": {
        "grinder": {"road": 3, "mountain": 5},
        "polisher": {"road": 2, "mountain": 2.5},
    },
    "capacity": {"grinder": 12, "polisher": 12},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    model.produce = pyo.Var(model.P, within=pyo.NonNegativeIntegers)

    def profit_rule(m):
        return sum(d["profit"][p] * m.produce[p] for p in m.P)

    model.obj = pyo.Objective(expr=profit_rule(model), sense=pyo.maximize)

    def capacity_rule(m, r):
        return sum(d["usage"][r][p] * m.produce[p] for p in m.P) <= d["capacity"][r]

    model.capacity = pyo.Constraint(model.R, rule=capacity_rule)

    return model


